<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';
import {router,Link,usePage} from '@inertiajs/vue3';
import {Plus,Search,ArrowUpRight,ShoppingBasket,Package,Clock,ShieldCheck,X,Trash2,ArrowRight,Wallet,FileText,AlertTriangle,CheckCircle2} from 'lucide-vue-next';
import Layout from '../Layout.vue';
import PrescriptionPicker from '../PrescriptionPicker.vue';
const props=defineProps({module:String,rows:Object,q:String,extra:Object});const page=usePage();const permissions=computed(()=>page.props.auth?.permissions||[]);const can=p=>permissions.value.includes(p);
const titles={dashboard:'Ringkasan apotek',products:'Produk & satuan',suppliers:'Pemasok',locations:'Lokasi penyimpanan',purchases:'Pesanan pembelian',receipts:'Penerimaan barang',stock:'Persediaan per batch',ledger:'Kartu stok',counts:'Stok opname',prescriptions:'Pelayanan resep',pos:'Kasir',sales:'Transaksi penjualan',shifts:'Shift kasir',temperatures:'Catatan suhu',finance:'Utang pemasok',returns:'Retur & refund',audit:'Audit aktivitas',users:'Pengguna'};
const desc={products:'Kelola identitas produk, harga jual, dan konversi satuan.',receipts:'Catat faktur dan batch. Stok tersedia setelah verifikasi apoteker.',stock:'Telusuri saldo, kedaluwarsa, dan kelayakan setiap batch.',ledger:'Setiap perubahan saldo tercatat dengan dokumen sumber.',counts:'Hitung fisik, periksa selisih, lalu posting koreksi dengan persetujuan.',prescriptions:'Telaah, siapkan, dan periksa resep sebelum penyerahan.',shifts:'Pisahkan uang tunai di laci dari pembayaran nontunai.',temperatures:'Rentang suhu mengikuti pengaturan masing-masing lokasi.',finance:'Penerimaan barang dan pembayaran pemasok dicatat terpisah.',audit:'Jejak tindakan pengguna dan dokumen sumber.',suppliers:'Identitas dan verifikasi dokumen pemasok.',users:'Akun dan peran sesuai kewenangan.',locations:'Rak, gudang, dan lokasi dengan rentang suhu tersendiri.',sales:'Status pembayaran dan penyerahan disimpan terpisah.'};
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);const num=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:4}).format(n||0);const date=n=>n?new Date(n).toLocaleString('id-ID',{timeZone:page.props.timezone,dateStyle:'medium',...(String(n).includes('T')?{timeStyle:'short'}:{})}):'—';
const searchHint=computed(()=>({products:'Nama produk, SKU, atau barcode…',pos:'Nama produk, SKU, atau barcode…',prescriptions:'Nomor resep, nama pasien, atau dokter…',sales:'Nomor transaksi atau nama kasir…',purchases:'Nomor pesanan atau pemasok…',receipts:'Nomor penerimaan, faktur, atau pemasok…',finance:'Nomor penerimaan atau pemasok…',returns:'Nomor transaksi atau produk…',shifts:'Nama kasir…',audit:'Tindakan, dokumen, atau petugas…',users:'Nama atau email…',locations:'Nama atau jenis lokasi…',temperatures:'Nama lokasi…'}[props.module]||'Nama produk atau batch…'));
const search=ref(props.q||'');function doSearch(){router.get(props.module==='dashboard'?'/':'/'+props.module,{q:search.value},{preserveState:true,replace:true});}
const labels={patient_name:'Pasien',quantity_base:'Jumlah satuan dasar',assessment:'Penilaian barang',assessment_note:'Catatan penilaian',condition:'Kondisi barang',refund_state:'Refund',amount:'Jumlah rupiah',reference:'Referensi',name:'Nama',sku:'SKU',barcode:'Barcode',generic:'Zat aktif',category:'Golongan',base_unit:'Satuan dasar',minimum_stock:'Stok minimum',available:'Tersedia',license:'Dokumen izin',license_expires:'Berlaku sampai',address:'Alamat',contact:'Kontak',verified:'Verifikasi',type:'Jenis',temperature_min:'Minimum °C',temperature_max:'Maksimum °C',number:'Nomor dokumen',invoice:'Faktur',status:'Status',due_date:'Jatuh tempo',supplier:'Pemasok',total_cost:'Nilai perolehan',batch:'Batch',expires_at:'Kedaluwarsa',recalled:'Penarikan',location:'Lokasi',quantity:'Saldo',cost_per_base:'Biaya/satuan dasar',delta:'Mutasi',balance_after:'Saldo sesudah',kind:'Jenis mutasi',source_type:'Dokumen sumber',source_id:'ID sumber',user:'Petugas',reason:'Alasan',created_at:'Waktu',counted:'Hitungan fisik',snapshot:'Saldo snapshot',date:'Tanggal resep',doctor:'Dokter',review:'Catatan telaah',total:'Total',payment_status:'Pembayaran',delivery_status:'Penyerahan',cashier:'Kasir',opening_cash:'Modal awal',expected_cash:'Kas seharusnya',counted_cash:'Kas fisik',difference:'Selisih',closed_at:'Ditutup',approved_by:'Persetujuan',note:'Catatan',value:'Suhu °C',minimum:'Minimum °C',maximum:'Maksimum °C',deviation:'Penyimpangan',action:'Tindakan',paid:'Dibayar',outstanding:'Sisa utang',data:'Detail',email:'Email',role:'Peran',active:'Aktif',credential_expires:'Kewenangan berlaku'};
const statuses={pending:'Menunggu verifikasi',posted:'Diposting',available:'Layak jual',quarantine:'Karantina',paid:'Lunas',unverified:'Belum diverifikasi',delivered:'Diserahkan',received:'Diterima',reviewed:'Ditelaah',prepared:'Disiapkan',approved:'Disetujui',partial:'Diterima sebagian',checked:'Siap di kasir',unfit:'Tidak layak',draft:'Draft',obat_bebas:'Obat bebas',obat_keras:'Obat keras',suplemen:'Suplemen',alkes:'Alat kesehatan',opening:'Saldo awal',sale:'Penjualan',receipt:'Penerimaan'};
const columns=computed(()=>{const row=props.rows?.data?.[0];return row?Object.keys(row).filter(k=>labels[k]&&!['created_at','data'].includes(k)||k==='created_at'||(props.module==='audit'&&k==='data')):[]});
function format(k,v){if(k==='assessment')return ({pending:'Menunggu penilaian',quarantine:'Tetap karantina',unfit:'Tidak layak jual'})[v]||v;if(k==='delivery_status'&&v==='pending')return 'Belum selesai';if(v===null)return '—';if(['total','total_cost','sale_price','cost_per_base','opening_cash','expected_cash','counted_cash','difference','paid','outstanding','amount'].includes(k))return money(v);if(['created_at','closed_at','due_date','expires_at','date','license_expires','credential_expires'].includes(k))return date(v);if(typeof v==='boolean')return v?'Ya':'Tidak';if(['status','payment_status','delivery_status','category','kind'].includes(k))return statuses[v]||v;if(['quantity','available','minimum_stock','delta','balance_after','counted','snapshot'].includes(k))return num(v);return v;}
const mode=ref('');
const form=reactive({});
const formErrors=ref({});
const saving=ref(false);
const selectedProduct=ref(null);
const lookupQuery=ref('');
const options=ref([]);
const lookupError=ref('');
const lines=ref([]);
let timer;
let lookupRequest;
watch(lookupQuery,value=>{
 clearTimeout(timer);
 lookupRequest?.abort();
 options.value=[];
 lookupError.value='';
 if(value.trim().length<2)return;
 timer=setTimeout(async()=>{
  const request=new AbortController();
  lookupRequest=request;
  try {
   const response=await fetch('/lookup/products?q='+encodeURIComponent(value),{headers:{Accept:'application/json'},signal:request.signal});
   if(!response.ok)throw new Error('lookup');
   const result=await response.json();
   if(lookupQuery.value===value)options.value=result;
  } catch(error){if(error.name!=='AbortError')lookupError.value='Pencarian produk gagal. Coba lagi atau masuk ulang jika sesi berakhir.';}
 },250);
});
onBeforeUnmount(()=>{clearTimeout(timer);lookupRequest?.abort();});
function choose(product){selectedProduct.value=product;addLine();}
function addLine(){
 if(!selectedProduct.value)return;
 const p=selectedProduct.value;
 if(['prescription','purchase'].includes(mode.value)&&lines.value.some(line=>line.product_id===p.id)){
  formErrors.value.items='Produk sudah ada. Ubah jumlah pada item yang sudah ditambahkan.';
 }else{
  lines.value.push({product_id:p.id,name:p.name,base_unit:p.base_unit,unit_id:p.units[0].id,units:p.units,quantity:'1',quantity_base:'1',batch:'',expires_at:'',unit_cost:'0'});
  delete formErrors.value.items;
 }
 selectedProduct.value=null;
 lookupQuery.value='';
 options.value=[];
}
const fields=computed(()=>({product:[['sku','SKU'],['barcode','Barcode'],['name','Nama produk'],['generic','Zat aktif'],['base_unit','Satuan dasar'],['category','Golongan','select',['obat_bebas','obat_bebas_terbatas','obat_keras','suplemen','alkes','narkotika','psikotropika','prekursor','oot']],['minimum_stock','Stok minimum','number'],['unit_price','Harga satuan dasar','number'],['strip_factor','Konversi strip (opsional)','number'],['strip_price','Harga strip','number'],['box_factor','Konversi dus (opsional)','number'],['box_price','Harga dus','number']],purchase:[['supplier_id','Pemasok','supplier']], 'return.assess':[['assessment','Penilaian barang','select',['quarantine','unfit']],['assessment_note','Catatan penilaian','textarea']],refund:[['reference','Referensi dana refund melalui bank'],['reason','Alasan pencatatan refund','textarea']],supplier:[['name','Nama pemasok'],['license','Identitas dokumen izin'],['license_expires','Masa berlaku','date'],['contact','Kontak'],['address','Alamat']],location:[['name','Nama lokasi'],['type','Jenis','select',['rak','gudang','lemari','kulkas','karantina']],['temperature_min','Suhu minimum °C (opsional)','number'],['temperature_max','Suhu maksimum °C (opsional)','number']],receipt:[['purchase_order_id','Pesanan pembelian (opsional)','order'],['supplier_id','Pemasok','supplier'],['invoice','Nomor faktur'],['due_date','Jatuh tempo','date'],['location_id','Lokasi','location']],prescription:[['number','Nomor resep'],['date','Tanggal resep','date'],['patient_name','Nama pasien'],['doctor','Dokter'],['notes','Catatan']], 'prescription.advance':[['review','Catatan telaah / proses / pemeriksaan','textarea']], 'shift.open':[['opening_cash','Modal awal tunai','number']], 'shift.close':[['counted_cash','Hitungan kas fisik','number'],['note','Penjelasan penutupan','textarea']],cash:[['amount','Jumlah (+ masuk, − keluar)','number'],['reason','Alasan','textarea']], 'count.submit':[['counted','Jumlah hitungan fisik','number'],['reason','Alasan selisih / hasil hitung','textarea']],temperature:[['location_id','Lokasi','location'],['value','Suhu °C','number'],['action','Tindakan koreksi bila menyimpang','textarea']], 'supplier.pay':[['amount','Jumlah pembayaran','number'],['reference','Referensi pembayaran']],user:[['name','Nama pengguna'],['email','Email','email'],['password','Kata sandi (minimal 12 karakter)','password'],['role','Peran','select',['pemilik','admin','ttk','gudang','kasir','auditor']]]}[mode.value]||[]));
function open(action,row={}){
 mode.value=action;
 for(const key of Object.keys(form))delete form[key];
 formErrors.value={};
 for(const [key] of fields.value)form[key]='';
 Object.assign(form,{id:row.id,receipt_id:row.id,customer_return_id:row.id,expected_status:row.status,idempotency_key:crypto.randomUUID(),opening_cash:'0',category:'obat_bebas',minimum_stock:'0',base_unit:'tablet',role:'kasir',checklist:{packaging:false,documents:false,quantity:false}});
 if(action==='prescription')form.date=new Intl.DateTimeFormat('en-CA',{timeZone:page.props.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 lines.value=[];
 selectedProduct.value=null;
 lookupQuery.value='';
 options.value=[];
}
watch(()=>form.purchase_order_id,id=>{const order=props.extra?.orders?.find(order=>order.id===Number(id));if(order)form.supplier_id=order.supplier_id;});
function submit(){
 if(saving.value)return;
 formErrors.value={};
 if(['receipt','prescription','purchase'].includes(mode.value)&&!lines.value.length){
  formErrors.value.items=mode.value==='prescription'?'Tambahkan minimal satu obat. Cari produk lalu pilih hasil pencarian agar obat masuk ke daftar resep.':'Tambahkan minimal satu produk penerimaan.';
  return;
 }
 const data={};
 for(const [key] of fields.value)data[key]=form[key]===''||form[key]===undefined?null:form[key];
 for(const key of ['id','receipt_id','customer_return_id','expected_status','idempotency_key'])if(form[key])data[key]=form[key];
 if(mode.value==='product'){
  data.units=[{name:form.base_unit,factor:'1',sale_price:String(form.unit_price)}];
  if(form.strip_factor)data.units.push({name:'strip',factor:String(form.strip_factor),sale_price:String(form.strip_price)});
  if(form.box_factor)data.units.push({name:'dus',factor:String(form.box_factor),sale_price:String(form.box_price)});
  for(const key of ['unit_price','strip_factor','strip_price','box_factor','box_price'])delete data[key];
 }
 if(mode.value==='purchase')data.items=lines.value.map(({product_id,unit_id,quantity})=>({product_id,unit_id,quantity:String(quantity)}));
 if(mode.value==='receipt'){
  data.items=lines.value.map(({product_id,unit_id,quantity,batch,expires_at,unit_cost})=>({product_id,unit_id,quantity:String(quantity),batch,expires_at,unit_cost:String(unit_cost)}));
  data.checklist=form.checklist;
 }
 if(mode.value==='prescription')data.items=lines.value.map(line=>({product_id:line.product_id,quantity_base:String(line.quantity_base)}));
 saving.value=true;
 router.post('/actions/'+mode.value,data,{onSuccess:()=>mode.value='',onError:errors=>formErrors.value=errors,onFinish:()=>saving.value=false});
}
function quick(action,row){router.post('/actions/'+action,{id:row.id,...(action==='count'?{layer_id:row.id}:{})});}
const cart=ref([]);const payment=ref('cash');const tendered=ref('');const reference=ref('');const selectedPrescription=ref(null);const received=ref(false);
watch(payment,()=>{received.value=false;reference.value='';});const saleError=ref({});const checkoutKey=ref(crypto.randomUUID());const busy=ref(false);
const subtotal=computed(()=>cart.value.reduce((sum,i)=>sum+Number(i.quantity)*Number(i.units.find(u=>u.id===Number(i.unit_id))?.sale_price||0),0));
function cartAdd(p){const found=cart.value.find(i=>i.product_id===p.id);if(found)found.quantity=String(Number(found.quantity)+1);else cart.value.push({product_id:p.id,name:p.name,unit_id:p.units[0].id,quantity:'1',units:p.units});}
function usePrescription(rx){
 selectedPrescription.value=rx;
 cart.value=rx.items.filter(item=>Number(item.remaining_base)>0).map(item=>({product_id:item.product_id,name:item.name,unit_id:item.units.find(unit=>unit.name===item.base_unit&&Number(unit.factor)===1).id,quantity:String(item.remaining_base),units:item.units}));
 saleError.value={};
 tendered.value='';
}
function clearPrescription(){selectedPrescription.value=null;cart.value=[];saleError.value={};tendered.value='';}
function checkout(){busy.value=true;router.post('/actions/sale',{idempotency_key:checkoutKey.value,items:cart.value.map(i=>({product_id:i.product_id,unit_id:Number(i.unit_id),quantity:String(i.quantity)})),payments:[{method:payment.value,amount:subtotal.value.toFixed(2),tendered:payment.value==='cash'?String(tendered.value||subtotal.value.toFixed(2)):subtotal.value.toFixed(2),reference:reference.value||null,received:received.value}],prescription_id:selectedPrescription.value?.id||null,discount:'0'},{onError:e=>saleError.value=e,onFinish:()=>busy.value=false});}
const actionTitles={purchase:'Pesanan pembelian',refund:'Catat refund melalui bank','return.assess':'Penilaian barang retur',product:'Produk baru',supplier:'Pemasok baru',location:'Lokasi baru',receipt:'Penerimaan barang',prescription:'Resep baru','prescription.advance':'Catatan pelayanan resep','shift.open':'Buka shift kasir','shift.close':'Tutup shift kasir','count.submit':'Hitungan fisik opname',temperature:'Catatan suhu','supplier.pay':'Pembayaran pemasok',user:'Pengguna baru',cash:'Pergerakan kas'};
function rowHasActions(row){
 const m=props.module;
 if(['purchases','receipts','prescriptions','sales'].includes(m))return true;
 if(m==='returns')return (row.assessment==='pending'&&can('return.assess'))||(!row.refund_id&&can('refund'));
 if(m==='suppliers')return !row.verified&&can('receive.verify');
 if(m==='stock')return row.status!=='pending'&&can('stock.manage');
 if(m==='counts')return (row.status!=='posted'&&can('stock.manage')&&row.created_by===page.props.auth.user.id)||(row.status==='pending'&&can('stock.approve'));
 if(m==='shifts')return (!row.closed_at&&can('shift')&&row.user_id===page.props.auth.user.id)||(row.closed_at&&!row.approved_by&&can('shift.approve'));
 return m==='finance'&&Number(row.outstanding)>0&&can('finance');
}
const hasActions=computed(()=>props.rows?.data?.some(rowHasActions)||false);
const primaryAction=computed(()=>({purchases:can('purchase')?'purchase':null,products:can('master')?'product':null,suppliers:can('master')||can('master.supplier')?'supplier':null,locations:can('master')?'location':null,receipts:can('receive')?'receipt':null,prescriptions:can('pharmacy')?'prescription':null,shifts:can('shift')?'shift.open':null,temperatures:can('stock.manage')?'temperature':null,users:can('users')?'user':null}[props.module]));
</script>
<template><Layout :title="titles[module]" :module="module">
 <template v-if="module==='dashboard'"><div class="page-heading"><div><span class="eyebrow">RUANG KERJA HARI INI</span><h1>Ringkasan apotek<span class="heading-dot">.</span></h1><p>Persediaan tertib, pelayanan terpantau.</p></div><Link v-if="can('sales')" href="/pos" class="primary"><ShoppingBasket :size="17"/> Buka kasir <ArrowUpRight :size="17"/></Link><div v-else class="date-chip">{{new Date().toLocaleDateString('id-ID',{timeZone:page.props.timezone,day:'numeric',month:'long',year:'numeric'})}}</div></div>
 <div class="overview-banner"><div class="banner-icon"><ShieldCheck :size="30"/></div><div><strong>Satu ruang kerja. Setiap pergerakan tercatat.</strong><p>Hubungkan penerimaan, persediaan, dan penyerahan dengan dokumen sumber.</p></div><span>DATA CONTOH SINTETIS</span></div>
 <div class="metrics"><div v-for="card in extra.cards" :key="card.label" class="metric"><span>{{card.label}} <ClipboardList :size="19"/></span><strong>{{card.money?money(card.value):num(card.value)}}</strong><small>{{card.note}}</small></div></div>
 <div class="dashboard-grid"><section v-if="can('business.view')||can('sales')" class="panel"><div class="panel-heading"><div><h3>Transaksi terbaru</h3><p>Catatan pembayaran dan status penyerahan</p></div><Link href="/sales" class="text-link">Lihat semua <ArrowUpRight :size="15"/></Link></div><table><thead><tr><th>Nomor transaksi</th><th>Total</th><th>Pembayaran</th><th>Penyerahan</th></tr></thead><tbody><tr v-for="s in extra.recent"><td><Link :href="'/sales/'+s.id">{{s.number}}</Link></td><td>{{money(s.total)}}</td><td><span class="status" :class="s.payment_status">{{statuses[s.payment_status]}}</span></td><td><span class="status" :class="s.delivery_status">{{s.delivery_status==='delivered'?'Selesai':'Belum selesai'}}</span></td></tr><tr v-if="!extra.recent.length"><td colspan="4" class="empty"><ShoppingBasket :size="28"/><strong>Belum ada penjualan</strong><span>Transaksi kasir yang disimpan akan muncul di sini.</span></td></tr></tbody></table></section><section v-else class="panel quick-panel"><h3>Tugas Anda</h3><p v-if="can('purchase')">Buat pesanan kebutuhan, catat penerimaan, periksa batch dan lokasi, lalu kirim hasil opname untuk persetujuan.</p><p v-if="can('pharmacy')">Telaah resep, periksa hasil penyiapan, verifikasi penerimaan, dan nilai kelayakan barang retur sesuai kewenangan.</p><p v-if="can('prepare')&&!can('pharmacy')">Catat penyiapan setelah resep ditelaah apoteker. Pemeriksaan akhir dan persetujuan tetap dilakukan apoteker.</p><p v-if="can('master')">Kelola produk, satuan, pemasok, lokasi, dan akun. Kewenangan teknis tidak memberikan persetujuan farmasi.</p></section><section class="panel quick-panel"><span class="eyebrow">ALUR KERJA</span><h3>Mulai dari sini</h3><Link v-if="can('purchase.view')" href="/purchases">Pesanan pembelian <ArrowRight :size="17"/></Link><Link v-if="can('prescription.view')" href="/prescriptions">Pelayanan resep <ArrowRight :size="17"/></Link><Link v-if="can('shift.view')" href="/shifts">Shift kasir <ArrowRight :size="17"/></Link><Link v-if="can('return.view')" href="/returns">Retur & refund <ArrowRight :size="17"/></Link><Link v-if="can('receipt.view')" href="/receipts"><span class="quick-icon"><Package :size="20"/></span><div><strong>Penerimaan barang</strong><small>Faktur, batch, dan verifikasi</small></div><ArrowRight :size="17"/></Link><Link v-if="can('inventory.view')" href="/stock"><span class="quick-icon"><ShieldCheck :size="20"/></span><div><strong>Periksa persediaan</strong><small>Saldo dan kelayakan per batch</small></div><ArrowRight :size="17"/></Link><Link v-if="can('inventory.view')" href="/ledger"><span class="quick-icon"><Clock :size="20"/></span><div><strong>Telusuri kartu stok</strong><small>Mutasi dan dokumen asal</small></div><ArrowRight :size="17"/></Link><p class="muted-note">Persetujuan farmasi hanya tersedia bagi apoteker dengan kewenangan aktif.</p></section></div></template>
 <template v-else><div class="page-heading"><div><span class="eyebrow">{{['pos','sales','shifts','prescriptions'].includes(module)?'OPERASIONAL':'PENGELOLAAN APOTEK'}}</span><h1>{{titles[module]}}<span class="heading-dot">.</span></h1><p>{{desc[module]||'Pencatatan terhubung dengan database apotek.'}}</p></div><button v-if="primaryAction" @click="open(primaryAction)" class="primary"><Plus :size="17"/>{{module==='shifts'?'Buka shift':'Tambah '+({products:'produk',suppliers:'pemasok',locations:'lokasi',receipts:'penerimaan',prescriptions:'resep',temperatures:'catatan',users:'pengguna',purchases:'pesanan'}[module]||'data')}}</button></div>
 <div v-if="module==='pos'&&!extra.shift&&can('shift')" class="warning"><AlertTriangle :size="20"/><div>Buka shift terlebih dahulu sebelum menerima pembayaran.</div><button @click="open('shift.open')" class="secondary">Buka shift</button></div>
 <div v-for="e in page.props.errors" class="error">{{e}}</div>
 <div :class="{'pos-grid':module==='pos'}"><section class="panel"><div class="table-toolbar"><form @submit.prevent="doSearch" class="search-box"><Search :size="18"/><input v-model="search" :placeholder="searchHint"/><button class="secondary">Cari</button></form><span class="record-count">{{rows?.total||0}} {{module==='pos'||module==='products'?'produk':'catatan'}}</span></div>
 <div v-if="module==='pos'" class="product-grid"><button v-for="p in rows?.data" class="product-card" @click="cartAdd(p)" :disabled="Number(p.available)<=0||p.special_control"><div class="product-symbol"><PillIcon/></div><div class="product-cat">{{statuses[p.category]||p.category}}</div><strong>{{p.name}}</strong><small>{{p.sku}} · {{num(p.available)}} {{p.base_unit}} tersedia</small><div class="product-bottom"><b>{{money(p.units[0]?.sale_price)}}</b><span><Plus :size="17"/></span></div><span v-if="p.requires_prescription" class="rx-label">Memerlukan resep</span></button></div>
 <div v-else class="table-scroll"><table><thead><tr><th v-for="c in columns">{{labels[c]}}</th><th v-if="hasActions">Tindakan</th></tr></thead><tbody><tr v-for="row in rows?.data" :key="row.id"><td v-for="c in columns"><span v-if="['status','payment_status','delivery_status','category'].includes(c)" class="status" :class="row[c]">{{format(c,row[c])}}</span><template v-else>{{format(c,row[c])}}</template></td><td v-if="hasActions" class="row-actions"><Link v-if="module==='purchases'||module==='receipts'" :href="'/documents/'+module+'/'+row.id" class="text-link">Periksa detail</Link><button v-if="module==='purchases'&&row.status==='draft'&&can('purchase.approve')" @click="quick('purchase.approve',row)">Setujui pesanan</button><Link v-if="module==='prescriptions'" :href="'/prescriptions/'+row.id" class="text-link">Detail resep</Link><button v-if="module==='returns'&&row.assessment==='pending'&&can('return.assess')" @click="open('return.assess',row)">Nilai barang</button><button v-if="module==='returns'&&!row.refund_id&&can('refund')" @click="open('refund',row)">Catat refund</button><Link v-if="module==='sales'" :href="'/sales/'+row.id" class="text-link">Detail <ArrowUpRight :size="14"/></Link><button v-if="module==='suppliers'&&!row.verified&&can('receive.verify')" @click="quick('supplier.verify',row)">Verifikasi</button><button v-if="module==='stock'&&row.status!=='pending'&&can('stock.manage')" @click="quick('count',row)">Mulai opname</button><button v-if="module==='counts'&&row.status==='draft'&&can('stock.manage')&&row.created_by===page.props.auth.user.id" @click="open('count.submit',row)">Isi hitungan</button><button v-if="module==='counts'&&row.status!=='posted'&&can('stock.manage')&&row.created_by===page.props.auth.user.id" @click="quick('count.recount',row)">Hitung ulang</button><button v-if="module==='counts'&&row.status==='pending'&&can('stock.approve')" @click="quick('count.approve',row)">Setujui koreksi</button><button v-if="module==='prescriptions'&&((row.status==='reviewed'&&can('prepare'))||(['received','prepared'].includes(row.status)&&can('pharmacy')))" @click="open('prescription.advance',row)">{{({received:'Telaah resep',reviewed:'Catat penyiapan',prepared:'Selesaikan pemeriksaan'})[row.status]||'Lanjutkan proses'}}</button><button v-if="module==='shifts'&&!row.closed_at&&can('shift')&&row.user_id===page.props.auth.user.id" @click="open('shift.close',row)">Tutup shift</button><button v-if="module==='shifts'&&!row.closed_at&&can('shift')&&row.user_id===page.props.auth.user.id" @click="open('cash',row)">Kas masuk/keluar</button><button v-if="module==='shifts'&&row.closed_at&&!row.approved_by&&can('shift.approve')" @click="quick('shift.approve',row)">Setujui</button><button v-if="module==='finance'&&Number(row.outstanding)>0&&can('finance')" @click="open('supplier.pay',row)">Bayar</button></td></tr><tr v-if="!rows?.data?.length"><td :colspan="columns.length+(hasActions?1:0)" class="empty"><ClipboardIcon/><strong>Belum ada catatan</strong><span>Data yang disimpan melalui proses operasional akan muncul di sini.</span></td></tr></tbody></table></div><div v-if="rows?.last_page>1" class="pagination"><Link v-for="link in rows.links" :href="link.url||'#'" :class="{selected:link.active,disabled:!link.url}" v-html="link.label"/></div></section>
 <aside v-if="module==='pos'" class="panel cart"><div class="panel-heading"><div><h3>Keranjang penjualan</h3><p>{{cart.length}} produk · {{extra.shift?'Shift #'+extra.shift.id:'Shift belum dibuka'}}</p></div><ShoppingBasket :size="23"/></div><div v-if="!cart.length" class="empty"><ShoppingBasket :size="35"/><strong>Siap melayani</strong><span>Pilih produk untuk memulai transaksi.</span></div><div v-for="(i,index) in cart" class="cart-item"><div><strong>{{i.name}}</strong><button @click="cart.splice(index,1)"><Trash2 :size="15"/></button></div><div><select v-model="i.unit_id"><option v-for="unit in i.units" :value="unit.id">{{unit.name}}</option></select><input v-model="i.quantity" type="number" step="0.0001" min="0.0001"/><b>{{money(Number(i.quantity)*Number(i.units.find(u=>u.id===Number(i.unit_id))?.sale_price))}}</b></div></div><div class="cart-payment"><PrescriptionPicker :selected="selectedPrescription" :has-cart="cart.length>0" @select="usePrescription" @clear="clearPrescription"/><label>Metode pembayaran<select v-model="payment"><option value="cash">Tunai</option><option value="transfer">Transfer manual</option><option value="card">Kartu manual</option><option value="qris">QRIS manual</option></select></label><label v-if="payment==='cash'">Uang diterima<input v-model="tendered" type="number" min="0" :placeholder="String(subtotal)"/></label><label v-else>Referensi pembayaran<input v-model="reference" placeholder="Nomor bukti pembayaran"/></label><label v-if="['transfer','qris'].includes(payment)" class="payment-received"><input v-model="received" type="checkbox"/>Dana pembayaran sudah diterima</label><p v-if="['transfer','qris'].includes(payment)" class="muted-note">Periksa bukti pembayaran pada aplikasi bank/merchant, lalu konfirmasi dana diterima di sini.</p><div class="cart-total"><span>Total</span><strong>{{money(subtotal)}}</strong></div><small v-if="payment==='cash'&&Number(tendered)>=subtotal">Kembalian {{money(Number(tendered)-subtotal)}}</small><div v-for="e in saleError" class="error">{{e}}</div><button class="primary" :disabled="!cart.length||!extra.shift||busy||(['transfer','qris'].includes(payment)&&(!received||!reference.trim()))" @click="checkout">{{busy?'Menyimpan…':'Bayar & selesaikan'}}<ArrowRight :size="18"/></button></div></aside></div></template>
 <div v-if="mode" class="modal-backdrop" @click.self="mode=''"><section class="modal"><div class="panel-heading"><div><span class="eyebrow">PENCATATAN APOTEK</span><h3>{{actionTitles[mode]||'Catatan operasional'}}</h3></div><button @click="mode=''"><X :size="22"/></button></div><form @submit.prevent="submit"><div class="form-grid"><label v-for="[key,label,type,choices] in fields" :class="{'full-width':type==='textarea'}">{{label}}<select v-if="type==='select'" v-model="form[key]"><option v-for="c in choices" :value="c">{{statuses[c]||c}}</option></select><select v-else-if="['supplier','location','order'].includes(type)" v-model="form[key]"><option value="">Pilih {{label}}</option><option v-for="c in (type==='supplier'?extra.suppliers:type==='order'?extra.orders:extra.locations)" :value="c.id">{{c.name||c.number}}</option></select><textarea v-else-if="type==='textarea'" v-model="form[key]" rows="3"/><input v-else v-model="form[key]" :type="type||'text'" :step="type==='number'?'any':undefined"/></label></div>
 <template v-if="['receipt','prescription','purchase'].includes(mode)"><div class="line-picker"><label>Cari produk<input v-model="lookupQuery" placeholder="Ketik minimal 2 karakter"/></label><div class="lookup-results" v-if="options.length"><button v-for="p in options" type="button" @click="choose(p)">{{p.name}} · {{p.sku}}</button></div><p class="item-help">Pilih hasil pencarian untuk menambahkan produk ke daftar di bawah.</p></div><div v-if="lookupError" class="error">{{lookupError}}</div><div v-if="!lines.length" class="item-help">Belum ada item. Resep atau penerimaan harus memiliki minimal satu produk.</div><div v-for="(line,i) in lines" :key="i" class="receipt-line"><div><strong>{{line.name}}</strong><button type="button" @click="lines.splice(i,1)"><X :size="16"/></button></div><div class="form-grid" v-if="['receipt','purchase'].includes(mode)"><label>Satuan<select v-model="line.unit_id"><option v-for="u in line.units" :value="u.id">{{u.name}} (×{{u.factor}})</option></select></label><label>Jumlah<input v-model="line.quantity" type="number" min="0.0001" step="any"/></label><label v-if="mode==='receipt'">Nomor batch<input v-model="line.batch"/></label><label v-if="mode==='receipt'">Kedaluwarsa<input v-model="line.expires_at" type="date"/></label><label v-if="mode==='receipt'">Biaya per satuan beli<input v-model="line.unit_cost" type="number" min="0" step="0.01"/></label></div><label v-else>Jumlah dalam satuan dasar ({{line.base_unit}})<input v-model="line.quantity_base" type="number" step="any" min="0.0001"/></label></div></template>
 <div v-if="mode==='receipt'" class="checklist"><label><input type="checkbox" v-model="form.checklist.packaging"/>Kemasan sesuai</label><label><input type="checkbox" v-model="form.checklist.documents"/>Dokumen sesuai</label><label><input type="checkbox" v-model="form.checklist.quantity"/>Jumlah sesuai</label></div><div v-for="e in formErrors" class="error">{{e}}</div><div class="modal-actions"><button class="secondary" type="button" @click="mode=''">Batal</button><button class="primary" :disabled="saving">{{saving?'Menyimpan…':'Simpan catatan'}} <CheckCircle2 :size="17"/></button></div></form></section></div>
 </Layout></template>
<script>
import {Pill,ClipboardList} from 'lucide-vue-next';
export default {components:{PillIcon:Pill,ClipboardIcon:ClipboardList}};
</script>
